fn binary_search(v: &Vec<u64>, k: u64) -> usize {
    let n = v.len();
    debug_assert!(n > 0);

    // We maintain an inclusive interval [lo, hi] that is guaranteed (by assumption)
    // to contain at least one occurrence of k.
    let mut lo: usize = 0;
    let mut hi: usize = n - 1;

    while lo < hi {
        // mid is always in [lo, hi). Using this form avoids overflow.
        let mid = lo + (hi - lo) / 2;

        if v[mid] < k {
            // k cannot be at mid or any index < mid, so keep (mid+1..=hi)
            lo = mid + 1;
        } else {
            // v[mid] >= k. Since k exists in [lo, hi], it must be in [lo, mid].
            hi = mid;
        }
        // Interval size strictly decreases each iteration, so the loop terminates.
    }

    debug_assert!(lo < n);
    debug_assert!(v[lo] == k);
    lo
}